{
  "edit_type": "precise_composite_overlay_dual_interaction_english_ui",

  "source": {
    "_hint": "Base Logic: Character sitting on Background. Background is fixed EXCEPT for the specific text on the button.",
    "mode": "IMAGE_COMPOSITION",
    "reference_images": {
      "foreground": "character_ref_image",
      "background_canvas": "profile_page_screenshot"
    },
    "consistency": {
      "character_fidelity": "high",
      "background_structure": "rigid_layout_preservation"
    }
  },

  "account_metadata": {
    "_hint": "Profile content to be displayed on the background canvas",
    "account_name": "电磁波Studio",
    "account_handle": "@电磁波Studio",
    "account_bio": "AI视频创作者 | 大学计算机教师\n特别喜欢玩刚出炉的AIGC大模型\n日常会分享ComfyUI的相关教程",
    "account_avatar": {
      "source": "character_ref_image",
      "content": "the_cat_from_reference_image",
      "placement": "top_left_circular_profile_picture",
      "crop_style": "circular_mask_centered_on_cat_face",
      "size": "standard_avatar_thumbnail",
      "border": "subtle_white_or_transparent_ring_if_needed"
    },
    "name_location": "top_left_next_to_avatar",
    "bio_location": "below_account_name_in_profile_section"
  },

  "ui_text_enforcement": {
    "_hint": "CRITICAL: Ensure the button text reads 'Follow' in English, regardless of the text in the original screenshot.",
    "target_element": "action_button_top_right",
    "mandatory_text": "Follow",
    "language": "English",
    "font_style": "sans_serif_bold_legible",
    "correction_policy": "overwrite_original_text_if_not_follow"
  },

  "background_preservation": {
    "_hint": "Background is a rigid floor. Only allow changes to shadows and the button text.",
    "policy": "strict_pixel_retention_mostly",
    "allowed_modifications": [
      "realistic_contact_shadows_under_character",
      "replacement_of_button_text_to_Follow",
      "insertion_of_circular_avatar_cat_at_top_left",
      "insertion_of_account_name_电磁波Studio_at_top_left",
      "insertion_of_bio_text_in_profile_description_area"
    ],
    "text_rendering": {
      "account_name_font": "bold_sans_serif",
      "bio_font": "regular_sans_serif",
      "chinese_character_support": "enabled",
      "line_breaks_preserved": true
    }
  },

  "camera_and_lighting": {
    "_hint": "Character sitting ON the interface.",
    "perspective": "high_angle_looking_down",
    "grounding_effect": {
      "technique": "contact_shadows_under_legs",
      "placement": "on_background_surface"
    }
  },

  "pose": {
    "_hint": "Dual pointing: Left Hand -> Avatar/Name area, Right Hand -> 'Follow' Button.",
    "pose_style": "sitting_cross_legged_or_kneeling",
    "head_position": "tilted_back_looking_at_camera",
    "hands_configuration": {
      "style": "dual_index_finger_pointing",
      "left_hand": {
        "action": "pointing_at_profile_identity",
        "target_location": "top_left_area",
        "specific_target": "circular_cat_avatar_and_name_电磁波Studio",
        "pointing_precision": "index_finger_towards_avatar_name_combo"
      },
      "right_hand": {
        "action": "pointing_at_follow_button",
        "target_location": "top_right_area",
        "specific_focus": "indicate_the_word_Follow"
      }
    }
  },

  "constraints": {
    "text_must_spell_Follow_correctly": true,
    "no_gibberish_text": true,
    "no_chinese_characters_on_button": true,
    "hands_must_not_block_the_word_Follow": true,
    "account_name_must_read_电磁波Studio_exactly": true,
    "bio_text_must_match_provided_content": true,
    "preserve_bio_line_breaks": true,
    "avatar_must_be_circular_crop_of_reference_cat": true,
    "avatar_position": "standard_top_left_profile_location",
    "character_and_avatar_distinction": "avatar_is_static_profile_image_on_background_character_is_sitting_figure"
  }
}

